# STRATEGY — swap algorithms at runtime
from abc import ABC, abstractmethod

class SortStrategy(ABC):
 @abstractmethod
 def sort(self, data: list) -> list:...

class QuickSort(SortStrategy):
 def sort(self, data): return sorted(data) # simplified

class MergeSort(SortStrategy):
 def sort(self, data): return sorted(data, key=lambda x: x)

class Sorter:
 def __init__(self, strategy: SortStrategy):
 self._strategy = strategy
 def set_strategy(self, s: SortStrategy): self._strategy = s
 def sort(self, data): return self._strategy.sort(data)

# OBSERVER — notify subscribers of events
class EventEmitter:
 def __init__(self):
 self._handlers: dict[str, list] = {}
 def on(self, event: str, handler):
 self._handlers.setdefault(event, []).append(handler)
 def emit(self, event: str, *args, **kwargs):
 for h in self._handlers.get(event, []):
 h(*args, **kwargs)

emitter = EventEmitter()
emitter.on("user.created", lambda u: print(f"Send welcome email to {u['email']}"))
emitter.on("user.created", lambda u: print(f"Log: new user {u['id']}"))
emitter.emit("user.created", {"id": 1, "email": "alice@example.com"})

# FACTORY — create objects without specifying exact class
class NotificationFactory:
 _registry = {}

 @classmethod
 def register(cls, name: str, notification_class):
 cls._registry[name] = notification_class

 @classmethod
 def create(cls, channel: str, **kwargs):
 if channel not in cls._registry:
 raise ValueError(f"Unknown channel: {channel}")
 return cls._registry[channel](**kwargs)

class EmailNotification:
 def __init__(self, to, subject, body):...

class SMSNotification:
 def __init__(self, phone, message):...

NotificationFactory.register("email", EmailNotification)
NotificationFactory.register("sms", SMSNotification)
notif = NotificationFactory.create("email", to="a@b.com", subject="Hi", body="Hello")

from dataclasses import dataclass, field
from typing import Optional

@dataclass
class HttpRequest:
 method: str
 url: str
 headers: dict[str, str]
 params: dict[str, str]
 body: Optional[str]
 timeout: int
 retries: int

class HttpRequestBuilder:
 def __init__(self, method: str, url: str):
 self._method = method
 self._url = url
 self._headers = {"Content-Type": "application/json", "Accept": "application/json"}
 self._params = {}
 self._body = None
 self._timeout = 30
 self._retries = 0

 def header(self, key: str, value: str) -> "HttpRequestBuilder":
 self._headers[key] = value
 return self # fluent interface - enable chaining

 def auth_bearer(self, token: str) -> "HttpRequestBuilder":
 return self.header("Authorization", f"Bearer {token}")

 def param(self, key: str, value: str) -> "HttpRequestBuilder":
 self._params[key] = value
 return self

 def body(self, data: str) -> "HttpRequestBuilder":
 self._body = data
 return self

 def timeout(self, seconds: int) -> "HttpRequestBuilder":
 self._timeout = seconds
 return self

 def retries(self, n: int) -> "HttpRequestBuilder":
 self._retries = n
 return self

 def build(self) -> HttpRequest:
 if not self._url:
 raise ValueError("URL is required")
 return HttpRequest(
 method=self._method, url=self._url,
 headers=dict(self._headers), params=dict(self._params),
 body=self._body, timeout=self._timeout, retries=self._retries
)

# Fluent chaining makes intent clear:
request = (HttpRequestBuilder("POST", "https://api.example.com/users")
.auth_bearer("eyJhbGciOiJSUzI1...")
.header("X-Request-ID", "abc-123")
.param("version", "v2")
.body('{"name": "Alice", "email": "alice@example.com"}')
.timeout(10)
.retries(3)
.build())

THREE APPROACHES:

1. SHARED TABLES + ROW-LEVEL SECURITY (most common for SaaS):
-- Every table has tenant_id:
ALTER TABLE users ADD COLUMN tenant_id UUID NOT NULL;
ALTER TABLE orders ADD COLUMN tenant_id UUID NOT NULL;
CREATE INDEX ON users(tenant_id);
CREATE INDEX ON orders(tenant_id, created_at DESC);

-- PostgreSQL Row Level Security (automatic filtering):
ALTER TABLE users ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON users
 USING (tenant_id = current_setting(''app.tenant_id'')::UUID);

-- Set per-request in middleware:
await db.query(`SET app.tenant_id = ''${req.tenantId}''`);
-- Now ALL queries on this connection are auto-filtered to correct tenant.

2. SCHEMA PER TENANT (stronger isolation, more complexity):
CREATE SCHEMA tenant_abc;
CREATE TABLE tenant_abc.users (...);
-- Set search_path per connection:
SET search_path TO tenant_abc;
-- Migrations: must run across all schemas.

3. DATABASE PER TENANT (strongest isolation, hardest to operate):
-- Each customer = their own Postgres database.
-- Good for: enterprise with compliance requirements.
-- Bad for: operational complexity at scale.

MIDDLEWARE (Node.js):
app.use(async (req, res, next) => {
 // Resolve tenant from subdomain, JWT, or header
 const tenantId = req.headers["x-tenant-id"]
 ?? req.user?.tenantId
 ?? extractFromSubdomain(req.hostname);
 if (!tenantId) return res.status(401).json({ error: "No tenant context" });
 // For RLS approach:
 req.dbClient = await pool.connect();
 await req.dbClient.query(`SET app.tenant_id = ''${tenantId}''`);
 res.on("finish", () => req.dbClient?.release());
 next();
});

